    stormStatus: "G1 Minor Geomagnetic Watch",
    stormStatusSi: "G1 \u0DC3\u0DD4\u0DC5\u0DD4 \u0DB7\u0DD6\u0D9A\u0DCF\u0DB1\u0DCA\u0DAD \u0D9A\u0DD4\u0DAB\u0DCF\u0DA7\u0DD4 \u0D85\u0DC0\u0DAF\u0DCF\u0DB1\u0DB8",
    stormStatusTa: "G1 \u0B9A\u0BBF\u0BB1\u0BBF\u0BAF \u0BAA\u0BC1\u0BB5\u0BBF\u0B95\u0BBE\u0BA8\u0BCD\u0BA4 \u0BAA\u0BC1\u0BAF\u0BB2\u0BCD \u0BA8\u0BBF\u0BB2\u0BC8",
